#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using Rekindle;
namespace Rekindle.Editor {
 [InitializeOnLoad]public static class RuntimeValidation {
  static int phase,index;static double next;static Session session;static WorldInteractable[] nodes;static Character opponent;static Vector3 moveStart;static Keyboard testKeyboard;static float moveTime;static string report="";static bool active;
  static RuntimeValidation(){EditorApplication.update+=Update;if(SessionState.GetBool("RekindleSmoke",false))active=true;}
  [MenuItem("Rekindle/Run runtime walkthrough")]public static void Run(){InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;SessionState.SetBool("RekindleSmoke",true);active=true;phase=0;index=0;report="";EditorApplication.isPlaying=true;}
  static void Log(string text){report+=text+"\n";File.WriteAllText("Artifacts/runtime-validation.txt",report);Debug.Log(text);}
  static void Check(bool b,string text){if(!b)throw new Exception(text);Log("PASS "+text);}
  static void Update(){if(!EditorApplication.isPlaying&&!active&&File.Exists("Artifacts/smoke.request")){File.Delete("Artifacts/smoke.request");Run();return;}if(!active||!EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.1;try{switch(phase){
   case 0:session=UnityEngine.Object.FindFirstObjectByType<Session>();if(!session||session.Player.Health==null)return;Check(session.Menu,"Main menu initializes");Capture("01-arrival");session.Begin(false);Check(!session.Menu,"Begin journey enters gameplay");moveStart=session.Player.transform.position;testKeyboard=InputSystem.AddDevice<Keyboard>("RekindleTestKeyboard");moveTime=Time.time;InputSystem.QueueStateEvent(testKeyboard,new KeyboardState(Key.W));InputSystem.Update();phase=1;next+=1;break;
   case 1:if(Time.time-moveTime<1){InputSystem.QueueStateEvent(testKeyboard,new KeyboardState(Key.W));InputSystem.Update();return;}InputSystem.QueueStateEvent(testKeyboard,new KeyboardState());InputSystem.Update();InputSystem.RemoveDevice(testKeyboard);Check(Vector3.Distance(moveStart,session.Player.transform.position)>1,"Input System W moves CharacterController");session.Motor.Teleport(new Vector3(0,1,-9));nodes=UnityEngine.Object.FindObjectsByType<WorldInteractable>(FindObjectsInactive.Include,FindObjectsSortMode.None);var guide=nodes.First(n=>n.Id=="soul-hearth");session.Motor.Teleport(guide.transform.position+Vector3.back*2);guide.Interact();Check(session.Message.Contains("Soul Dragon"),"Elian introduces authored soul restoration premise");var gardener=nodes.First(n=>n.Id=="soul-garden");session.Motor.Teleport(gardener.transform.position+Vector3.back*2);gardener.Interact();Check(session.Message.Contains("Sera:"),"Lost souls retain individual authored identities");phase=2;index=0;break;
   case 2:var resources=nodes.Where(x=>x.Kind==InteractionKind.Resource).ToArray();if(index<resources.Length){var node=resources[index++];session.Motor.Teleport(node.transform.position+Vector3.back*2);node.Interact();}else{Check(session.Bag.Count("wood")>=15&&session.Bag.Count("stone")>=10&&session.Bag.Count("iron")>=4,"Gathering feeds shared inventory and depletes nodes");int beforeRepeat=session.Bag.Slots.Sum(x=>x.quantity);session.Motor.Teleport(resources[0].transform.position+Vector3.back*2);resources[0].Interact();Check(session.Bag.Slots.Sum(x=>x.quantity)==beforeRepeat,"Depleted gathering commands cannot duplicate inventory rewards");phase=3;}break;
   case 3:Restore("hearth");Restore("hearth");Check(session.World.Stage("hearth")==2,"House restoration completes through contextual commands");Restore("forge");Restore("garden");Restore("garden");Check(session.World.Stage("forge")==1,"Forge awaits identity anchor");opponent=UnityEngine.Object.FindObjectsByType<Character>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(c=>c.Id=="sanctuary-1");opponent.ReceiveDamage(1);var resetBrain=opponent.GetComponent<EnemyBrain>();resetBrain.ResetEncounter();Check(opponent.Health.Value==opponent.Health.Max&&resetBrain.State==EnemyState.Idle,"Encounter reset restores health and idle state");session.Motor.Teleport(opponent.transform.position+Vector3.back*2);session.Player.Evade(120);session.Combat.Select(opponent);phase=4;break;
   case 4:if(opponent.Alive){session.Motor.Teleport(opponent.transform.position+Vector3.back*2);session.Combat.TryAttack(false);}else{Check(session.World.IsDefeated("sanctuary-1"),"Shared combat defeats guardian and commits encounter progress");opponent=UnityEngine.Object.FindObjectsByType<Character>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(c=>c.Id=="warden");session.Motor.Teleport(opponent.transform.position+Vector3.back*2);session.Combat.Select(opponent);phase=5;Capture("02-sanctuary");}break;
   case 5:if(opponent.Alive){session.Motor.Teleport(opponent.transform.position+Vector3.back*2);session.Combat.TryAttack(false);}else{Check(session.World.BossDefeated&&session.Bag.Count("hammer")==1&&session.Bag.Count("ember")==1,"Boss combat releases both authored anchors and changes world phase");var gate=nodes.First(x=>x.Id=="return-gate");session.Motor.Teleport(gate.transform.position+Vector3.back*2);gate.Interact();Check(session.Player.transform.position.z<0,"Cleansed waystone returns player to settlement");phase=6;}break;
   case 6:Restore("forge");Check(session.Equipment.Improved,"Mira returns and equips Dawn Blade");Restore("beacon");Restore("beacon");Check(session.World.Complete,"Final restoration completes coherent story");session.ClosePanel();session.Motor.Teleport(new Vector3(0,1,-12));session.Save();var saved=session.Saves.Read(s=>new WorldState().Load(s,new Inventory()));Check(saved!=null&&saved.defeated.Contains("warden")&&saved.buildings.First(x=>x.id=="beacon").stage==2,"Saved snapshot retains restored world and dungeon state");phase=7;next+=2;break;
   case 7:Capture("03-rekindled");phase=8;next+=2;break;case 8:UnityEngine.SceneManagement.SceneManager.LoadScene(0);phase=9;next+=2;break;case 9:session=UnityEngine.Object.FindFirstObjectByType<Session>();if(!session||session.Player.Health==null)return;session.Begin(true);Check(session.World.Complete&&session.World.BossDefeated&&session.Equipment.Improved,"Continue restores final world phase, equipment, and dungeon after full scene reload");Check(!UnityEngine.Object.FindObjectsByType<EnemyBrain>(FindObjectsSortMode.None).Any(e=>e.GetComponent<Character>().Id=="warden"),"Defeated boss stays absent after Continue");Log("COMPLETE: Runtime command walkthrough; test teleports and temporary player invulnerability used. Combat timing, gathering, restoration, and save use production rules. Manual experience/visual assessment remains separate.");SessionState.SetBool("RekindleSmoke",false);active=false;EditorApplication.isPlaying=false;File.WriteAllText("Artifacts/build.request","Build validated slice");break;
  }}catch(Exception e){Log("FAIL "+e);SessionState.SetBool("RekindleSmoke",false);active=false;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());EditorApplication.isPlaying=false;}}
  static void Restore(string id){var b=nodes.First(x=>x.Id==id);session.Motor.Teleport(b.transform.position+Vector3.back*4);session.Inspect(b);session.RestoreBuilding();session.ClosePanel();}
  static void Capture(string name){ScreenCapture.CaptureScreenshot("Artifacts/"+name+"-hud.png");var camera=Camera.main;if(!camera)return;var rt=new RenderTexture(1600,900,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes("Artifacts/"+name+".png",t.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}
 }
}
#endif
